func (q *Queries) RotateLineageTokens(ctx context.Context, arg RotateLineageTokensParams) (int64, error) {
	result, err := q.db.Exec(ctx, rotateLineageTokens,
		arg.Presented,
		arg.RefreshHash,
		arg.TokenHash,
		arg.TokenExpiresAt,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const serverIdentities = `-- name: ServerIdentities :many
SELECT s.id,s.key_rotated_at,s.identity_conflict_at,s.identity_conflict,s.identity_conflict_epoch,s.enrollment_epoch,
    k.created_at AS key_created_at,l.created_at AS lineage_started_at
FROM servers s
LEFT JOIN agent_keys k ON k.server_id = s.id AND k.key_hash = s.credential_hash
LEFT JOIN agent_lineages l ON l.server_id = s.id AND l.superseded_at IS NULL
WHERE s.workspace_id = $1::uuid
`

type ServerIdentitiesRow struct {
	ID                    uuid.UUID   `json:"id"`
	KeyRotatedAt          *time.Time  `json:"key_rotated_at"`
	IdentityConflictAt    *time.Time  `json:"identity_conflict_at"`
	IdentityConflict      []byte      `json:"identity_conflict"`
	IdentityConflictEpoch pgtype.Int8 `json:"identity_conflict_epoch"`
	EnrollmentEpoch       int64       `json:"enrollment_epoch"`
	KeyCreatedAt          *time.Time  `json:"key_created_at"`
	LineageStartedAt      *time.Time  `json:"lineage_started_at"`
}

// A server has at most one live lineage. A conflict is shown only in the epoch it was raised in.
func (q *Queries) ServerIdentities(ctx context.Context, workspaceID uuid.UUID) ([]ServerIdentitiesRow, error) {
	rows, err := q.db.Query(ctx, serverIdentities, workspaceID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ServerIdentitiesRow{}
	for rows.Next() {
		var i ServerIdentitiesRow
		if err := rows.Scan(
			&i.ID,
			&i.KeyRotatedAt,
			&i.IdentityConflictAt,
			&i.IdentityConflict,
			&i.IdentityConflictEpoch,
			&i.EnrollmentEpoch,
			&i.KeyCreatedAt,
			&i.LineageStartedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const setServerKey = `-- name: SetServerKey :exec
UPDATE servers SET credential_hash = $1,previous_hash = NULL,previous_until = NULL,
    key_rotated_at = now(),rotate_key_requested = false
WHERE workspace_id = $2 AND id = $3
`

type SetServerKeyParams struct {
	KeyHash     []byte    `json:"key_hash"`
	WorkspaceID uuid.UUID `json:"workspace_id"`
	ServerID    uuid.UUID `json:"server_id"`
}

func (q *Queries) SetServerKey(ctx context.Context, arg SetServerKeyParams) error {
	_, err := q.db.Exec(ctx, setServerKey, arg.KeyHash, arg.WorkspaceID, arg.ServerID)
	return err
}

const startNewEpoch = `-- name: StartNewEpoch :one
UPDATE servers SET enrollment_epoch = enrollment_epoch + 1,consumed_code_hash = $1,
    retired_bearer_hash = NULL,bound_at = NULL,start_counter_floor = NULL,start_counter_floor_seq = NULL,
    identity_conflict_at = NULL,identity_conflict_epoch = NULL,identity_conflict = NULL,
    key_rotated_at = CASE WHEN $2::boolean THEN now() ELSE NULL END,rotate_key_requested = false
WHERE workspace_id = $3 AND id = $4
RETURNING enrollment_epoch
`

type StartNewEpochParams struct {
	CodeHash    []byte    `json:"code_hash"`
	KeyBound    bool      `json:"key_bound"`
	WorkspaceID uuid.UUID `json:"workspace_id"`
	ServerID    uuid.UUID `json:"server_id"`
}

// Consuming a one-time code is the only thing besides a bind that starts an epoch, and the only
// thing that clears an identity conflict.
func (q *Queries) StartNewEpoch(ctx context.Context, arg StartNewEpochParams) (int64, error) {
	row := q.db.QueryRow(ctx, startNewEpoch,
		arg.CodeHash,
		arg.KeyBound,
		arg.WorkspaceID,
		arg.ServerID,
	)
	var enrollment_epoch int64
	err := row.Scan(&enrollment_epoch)
	return enrollment_epoch, err
}

